let comboLiftCharges=0,comboLiftMax=2,comboLiftReady=true,comboLiftTimer=0;
// Combo Lift: raise all bricks when combo hits milestones, giving player breathing room

document.getElementById('scoreVal').textContent=score;
}

// Combo Lift: shift ALL bricks upward to give player more space
function liftAllBricks(amount=60){
  let shifted=0;
  for(let b of bricks){
    if(!b.alive)continue;
    if(b.y-amount>=10){ // Don't lift above screen top
      b.y-=amount;shifted++;
    }
  }
  if(shifted>0){
    addFloatText(W/2,H/2,'⬆ COMBO LIFT ⬆','#0f8',32);
    triggerShake(3,8);sfxPowerup();
    spawnParticles(W/2,H/2,'#0f8',30);
    // Consume one charge
    comboLiftCharges=Math.max(0,comboLiftCharges-1);
    updateComboLiftUI();
  }
}

// Check if combo milestone grants a free lift charge
function checkComboLift(){
  if(combo>=10&&comboLiftCharges<comboLiftMax){
    comboLiftCharges++;
    addFloatText(W/2,py-50,'⬆ LIFT CHARGE!','#0f8',22);
    updateComboLiftUI();
  }
}

function updateComboLiftUI(){
  let el=document.getElementById('combo-lift-ui');
  if(el){
    let charges='';
    for(let i=0;i<comboLiftMax;i++)charges+=i<comboLiftCharges?'●':'○';
    el.textContent='LIFT ['+charges+'] [S]';
    el.style.color=comboLiftCharges>0?'#0f8':'#666';
  }
}

